pickup.vre:effects:
carrying' = carrying == false
             && product.xpos == xpos
             && product.ypos == ypos
  ? product
  : carrying;
output.success = carrying == false
                 && product.xpos == xpos
                 && product.ypos == ypos;
output.carrying = carrying';

moveLeft.vre:effects:
xpos' = xpos - 1;
carrying.xpos' = (xpos - 1);
output.success = true;
output.xpos = xpos';

moveRight.vre:effects:
xpos' = xpos + 1;
carrying.xpos' = (xpos + 1);
output.success = true;
output.xpos = xpos';

moveUp.vre:effects:
ypos' = ypos - 1;
carrying.ypos' = (ypos - 1);
output.success = true;
output.ypos = ypos';

moveDown.vre:effects:
ypos' = ypos + 1;
carrying.ypos' = (ypos + 1);
output.success = true;
output.ypos = ypos';
